/* Menu button */
.menu-button {
  position: fixed;
  top: -32.5px;
  right: 15px;
  cursor: pointer;
  color: #ccc;
  z-index: 1001;
  background: none;
  border: none;
  transition: color 0.3s, transform 0.3s;
  transform: scale(2);
}

.menu-button.active {
  color: #fff;
}

/* Overlay */
#overlay {
  position: fixed;
  top: 100vh;               /* FIX: define default closed position */
  left: -0.1rem;                 /* FIX: was `left: 10` (invalid) */
  width: 100%;
  height: 100vh;
  background: rgba(0,0,0,0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(8px);
  opacity: 0;
  pointer-events: none;
  z-index: 1000;
  transition: opacity 1.3s, top 0.01s;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

}

/* Default (Chrome, most browsers) */
#overlay.active {
  top: -95vh;              /* unchanged, your original behavior */
  opacity: 1;
  pointer-events: auto;
}

/* Links */
#overlay .glass {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  text-align: center;
}

#overlay .nav-link {
  color: #ccc;
  font-size: 2rem;
  text-decoration: none;
  transition: color 0.3s;
}

#overlay .nav-link:hover {
  color: #fff;
}

.glass {
	line-height: 2.5rem;

}
